chdir='blueprint/src/chapters'
files=["Picard_QuotScheme.tex","Picard_GrassmannianQuot.tex","Picard_FlatteningStratification.tex","Picard_SectionGradedRing.tex","Picard_LineBundleCoherence.tex","Picard_GrassmannianCells.tex"]
# gather all lean declaration names in project
decls=set()
pat=re.compile(r'^\s*(?:@\[[^\]]*\]\s*)?(?:private\s+|protected\s+|noncomputable\s+|nonrec\s+)*(theorem|lemma|def|abbrev|instance|structure|class|inductive|opaque)\s+([A-Za-z_α-ω][^\s:({\[]*)',re.M)
ns_stack=[]
for f in glob.glob('AlgebraicJacobian/**/*.lean',recursive=True):
    cur=[]
    for line in open(f,encoding='utf-8'):
        m=re.match(r'^namespace\s+([\w.Γ-ω]+)',line)
        if m: cur.append(m.group(1)); continue
        m=re.match(r'^end\s+([\w.Γ-ω]+)',line)
        if m:
            if cur and cur[-1]==m.group(1): cur.pop()
            continue
        m=pat.match(line)
        if m:
            name=m.group(2)
            full='.'.join(cur+[name])
            decls.add(full); decls.add(name)
            for i in range(len(cur)):
                decls.add('.'.join(cur[i:]+[name]))
missing=collections.defaultdict(list)
for fn in files:
    txt=open(os.path.join(chdir,fn),encoding='utf-8').read().split('\n')
    for i,line in enumerate(txt,1):
        if line.strip().startswith('%'): continue
        for m in re.finditer(r'\\lean\{([^}]*)\}',line):
            for nm in m.group(1).split(','):
                nm=nm.strip()
                if not nm: continue
                if nm not in decls:
                    missing[fn].append((i,nm))
for fn in files:
    print('===',fn, len(missing[fn]),'missing')
    for i,nm in missing[fn]: print('  ',i,nm)
EOF
